def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    out = [row[:] for row in grid]

    # Find the horizontal template: a row containing a contiguous run of
    # non-background cells longer than a single isolated marker.
    template = None
    for row in grid:
        runs = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start >= 3:
                runs.append((start, row[start:c]))
        if runs:
            template = max(runs, key=lambda x: len(x[1]))
            break

    if template is None:
        return out
    start, motif = template
    n = len(motif)
    center_offset = n // 2

    # Isolated cells of a color not part of the template mark the placements.
    motif_colors = set(motif)
    markers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or grid[r][c] in motif_colors:
                continue
            markers.append((r, c))

    for r, c in markers:
        left = c - center_offset
        for k, color in enumerate(motif):
            x = left + k
            if 0 <= x < w:
                out[r][x] = color
    return out
